"""Immutable handoff for text generated by a Codex agent."""

from __future__ import annotations

import hashlib
import json
import re
import shutil
import stat
import tempfile
from pathlib import Path

from ..storage import RunLock, atomic_publish, fingerprint, write_json

_ID = re.compile(r"text_[0-9a-f]{64}\Z")
_MAX_BYTES = 20 * 1024 * 1024


class TextTaskPending(RuntimeError):
    def __init__(self, task_id: str):
        self.task_id = task_id
        super().__init__(f"Text task {task_id} awaits a Codex agent")


def _digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _no_links(path: Path) -> None:
    # Windows junctions and other reparse points are not always symlinks.
    path = path.absolute()
    for component in (path, *path.parents):
        try:
            info = component.lstat()
        except FileNotFoundError:
            continue
        if stat.S_ISLNK(info.st_mode) or (
            getattr(info, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
        ):
            raise ValueError("Text task paths cannot contain links or reparse points")


def _run_root(run: Path) -> Path:
    root = Path(run).expanduser().absolute()
    _no_links(root)
    if not root.is_dir():
        raise ValueError("Text task run must be an existing directory")
    return root.resolve(strict=True)


def _path(root: Path, name: str) -> Path:
    # All task-relative paths are fixed names or validated task IDs.
    if not name or name in {".", ".."} or "/" in name or "\\" in name or ":" in name:
        raise ValueError("Invalid text task path")
    path = root / name
    _no_links(path)
    if not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Text task path escapes its directory")
    return path


def _id(task_id: str) -> str:
    if not isinstance(task_id, str) or not _ID.fullmatch(task_id):
        raise ValueError("Invalid text task ID")
    return task_id


def _read(path: Path) -> bytes:
    _no_links(path)
    if not path.is_file():
        raise ValueError("Text task file is missing or invalid")
    with path.open("rb") as stream:
        data = stream.read(_MAX_BYTES + 1)
    if len(data) > _MAX_BYTES:
        raise ValueError("Text task file exceeds the size limit")
    return data


def _object(data: bytes) -> dict:
    def invalid_constant(value: str):
        raise ValueError(f"Invalid JSON constant: {value}")

    try:
        result = json.loads(data.decode("utf-8"), parse_constant=invalid_constant)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("Text task file must contain UTF-8 JSON") from exc
    if not isinstance(result, dict):
        raise ValueError("Text task JSON must be an object")
    return result


def _body(stage: str, prompt: str, episode_range: list[int] | None) -> dict:
    if not isinstance(stage, str) or not stage.strip():
        raise ValueError("Text task stage must be nonempty")
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("Text task prompt must be nonempty")
    if len(prompt.encode("utf-8")) > _MAX_BYTES:
        raise ValueError("Text task prompt exceeds the size limit")
    if episode_range is not None and (
        not isinstance(episode_range, list)
        or any(type(value) is not int for value in episode_range)
    ):
        raise ValueError("Text task episode range must be a list of integers or null")
    return {
        "stage": stage,
        "episode_range": episode_range,
        "prompt_sha256": _digest(prompt.encode("utf-8")),
        "prompt_file": "input.txt",
    }


def _describe(root: Path, task_id: str) -> dict:
    task_id = _id(task_id)
    directory = _path(_path(root, "text_tasks"), task_id)
    if not directory.is_dir():
        raise ValueError("Text task does not exist")
    request = _object(_read(_path(directory, "request.json")))
    expected = {"task_id", "task_sha256", "stage", "episode_range", "prompt_sha256", "prompt_file"}
    if set(request) != expected:
        raise ValueError("Invalid text task request fields")
    body = {k: v for k, v in request.items() if k not in {"task_id", "task_sha256"}}
    if (
        request["task_id"] != task_id
        or "text_" + fingerprint(body) != task_id
        or fingerprint({**body, "task_id": task_id}) != request["task_sha256"]
        or request["prompt_file"] != "input.txt"
    ):
        raise ValueError("Text task request identity or fingerprint does not match")
    prompt_file = _path(directory, "input.txt")
    prompt_data = _read(prompt_file)
    try:
        prompt = prompt_data.decode("utf-8")
    except UnicodeError as exc:
        raise ValueError("Text task prompt is not UTF-8") from exc
    if _body(request["stage"], prompt, request["episode_range"]) != body:
        raise ValueError("Text task input was changed")
    metadata = _path(directory, "response.json")
    response = None
    response_file = None
    if metadata.exists():
        response = _object(_read(metadata))
        if (
            set(response) != {"status", "task_sha256", "path", "sha256", "agent_id", "notes"}
            or response["status"] != "submitted"
            or response["task_sha256"] != request["task_sha256"]
            or response["path"] != "output.json"
            or not isinstance(response["agent_id"], str)
            or not response["agent_id"].strip()
            or not isinstance(response["notes"], str)
        ):
            raise ValueError("Invalid text task response metadata")
        response_file = _path(directory, "output.json")
        data = _read(response_file)
        _object(data)
        if _digest(data) != response["sha256"]:
            raise ValueError("Text task response was changed")
    return {
        "task_id": task_id,
        "status": "submitted" if response else "pending",
        "request": request,
        "response": response,
        "task_directory": str(directory),
        "prompt_file": str(prompt_file),
        "response_file": str(response_file) if response_file else None,
    }


def prepare_text_task(
    run: Path, *, stage: str, prompt: str, episode_range: list[int] | None = None
) -> str:
    """Freeze inputs under the caller's run lock, then pause or return submitted text."""
    root = _run_root(run)
    body = _body(stage, prompt, episode_range)
    task_id = "text_" + fingerprint(body)
    request_body = {**body, "task_id": task_id}
    request = {**request_body, "task_sha256": fingerprint(request_body)}
    tasks = _path(root, "text_tasks")
    tasks.mkdir(exist_ok=True)
    directory = _path(tasks, task_id)
    if directory.exists():
        if _describe(root, task_id)["request"] != request:
            raise ValueError("Text task ID conflicts with existing request")
    else:
        staging = Path(tempfile.mkdtemp(prefix=".staging-", dir=tasks))
        try:
            (staging / "input.txt").write_bytes(prompt.encode("utf-8"))
            write_json(staging / "request.json", request)
            _path(tasks, task_id)
            atomic_publish(staging, directory, replace=False)
        finally:
            if staging.exists():
                _no_links(staging)
                if (
                    staging.parent != tasks
                    or not staging.name.startswith(".staging-")
                    or not staging.resolve().is_relative_to(tasks.resolve())
                ):
                    raise ValueError("Invalid temporary text task directory")
                shutil.rmtree(staging)
    description = _describe(root, task_id)
    if description["response_file"]:
        return _read(Path(description["response_file"])).decode("utf-8")
    raise TextTaskPending(task_id)


def get_text_task(run: Path, task_id: str) -> dict:
    return _describe(_run_root(run), task_id)


def list_text_tasks(run: Path) -> list[dict]:
    root = _run_root(run)
    tasks = _path(root, "text_tasks")
    if not tasks.exists():
        return []
    if not tasks.is_dir():
        raise ValueError("Text task storage must be a directory")
    result = []
    for path in sorted(tasks.iterdir()):
        if path.name.startswith("."):
            continue
        _no_links(path)
        if not path.is_dir():
            raise ValueError("Invalid text task storage entry")
        result.append(_describe(root, path.name))
    return result


def complete_text_task(
    run: Path, task_id: str, file: Path, *, agent_id: str, notes: str = ""
) -> dict:
    if not isinstance(agent_id, str) or not agent_id.strip():
        raise ValueError("Text task requires a nonempty agent ID")
    if not isinstance(notes, str):
        raise ValueError("Text task notes must be a string")
    root = _run_root(run)
    _no_links(root / ".run.lock")
    with RunLock(root):
        description = _describe(root, task_id)
        data = _read(Path(file).expanduser())
        _object(data)
        digest = _digest(data)
        if description["response"]:
            if description["response"]["sha256"] != digest:
                raise ValueError("A different response is already submitted")
            return description
        directory = Path(description["task_directory"])
        output = _path(directory, "output.json")
        if output.exists():
            if _read(output) != data:
                raise ValueError("Text task output conflicts with existing file")
        else:
            with output.open("xb") as stream:
                stream.write(data)
        metadata = {
            "status": "submitted",
            "task_sha256": description["request"]["task_sha256"],
            "path": "output.json",
            "sha256": digest,
            "agent_id": agent_id.strip(),
            "notes": notes,
        }
        write_json(_path(directory, "response.json"), metadata)
        return _describe(root, task_id)
